// projectedDeliveryRepository runs the connection's projections over every
// Delivery write; see WithProjections. run performs a write through the
// repository it hands f and projects the changes f reports.
type projectedDeliveryRepository struct {
	DeliveryRepository
	run func(ctx context.Context, f func(DeliveryRepository) ([]repox.Change, error)) error
}

// getDelivery reads name through read, for a queued write's
// Change.LoadPrior (repox.PriorOf).
func getDelivery(ctx context.Context, read repox.Conn, name string) (*hooksv1.Delivery, error) {
	return New(read).Deliveries.Get(ctx, name)
}

// changedDelivery is the change one write of a Delivery makes.
func changedDelivery(name string, op repox.ChangeOp, rec *hooksv1.Delivery) []repox.Change {
	c := repox.Change{Type: "hooks.v1/Delivery", Name: name, Op: op}
	if rec != nil {
		c.Record = rec
	}
	return []repox.Change{c}
}

func (p *projectedDeliveryRepository) Create(ctx context.Context, parent string, m *hooksv1.Delivery) (out *hooksv1.Delivery, err error) {
	err = p.run(ctx, func(r DeliveryRepository) ([]repox.Change, error) {
		var err error
		out, err = r.Create(ctx, parent, m)
		return changedDelivery(out.GetName(), repox.ChangeCreate, out), err
	})
	return out, err
}

func (p *projectedDeliveryRepository) Update(ctx context.Context, m *hooksv1.Delivery, paths []string) (out *hooksv1.Delivery, err error) {
	err = p.run(ctx, func(r DeliveryRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, m.GetName()))
		if err != nil {
			return nil, err
		}
		out, err = r.Update(ctx, m, paths)
		return repox.WithPrior(changedDelivery(m.GetName(), repox.ChangeUpdate, out), prior), err
	})
	return out, err
}

func (p *projectedDeliveryRepository) UpdateOutputOnly(ctx context.Context, m *hooksv1.Delivery, paths []string) (out *hooksv1.Delivery, err error) {
	err = p.run(ctx, func(r DeliveryRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, m.GetName()))
		if err != nil {
			return nil, err
		}
		out, err = r.UpdateOutputOnly(ctx, m, paths)
		return repox.WithPrior(changedDelivery(m.GetName(), repox.ChangeUpdate, out), prior), err
	})
	return out, err
}

func (p *projectedDeliveryRepository) UpdateWithOutputOnly(ctx context.Context, m *hooksv1.Delivery, paths, outputPaths []string) (out *hooksv1.Delivery, err error) {
	err = p.run(ctx, func(r DeliveryRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, m.GetName()))
		if err != nil {
			return nil, err
		}
		out, err = r.UpdateWithOutputOnly(ctx, m, paths, outputPaths)
		return repox.WithPrior(changedDelivery(m.GetName(), repox.ChangeUpdate, out), prior), err
	})
	return out, err
}

func (p *projectedDeliveryRepository) Delete(ctx context.Context, name string) error {
	return p.run(ctx, func(r DeliveryRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, name))
		if err != nil {
			return nil, err
		}
		return repox.WithPrior(changedDelivery(name, repox.ChangeDelete, nil), prior), r.Delete(ctx, name)
	})
}

