// guardedDeliveryRepository keeps Delivery's references whole; see guard.
type guardedDeliveryRepository struct {
	DeliveryRepository
	refs *repox.References
}

func (g *guardedDeliveryRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "hooks.v1/Delivery", name)
	if err != nil {
		return err
	}
	if err := g.DeliveryRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, true)
	return nil
}

// resolveDeliveryReferences proves, through refs, that every external
// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolveDeliveryReferences(ctx context.Context, refs *repox.References, m *hooksv1.Delivery, paths []string) error {
	return nil
}

// queueDeliveryReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queueDeliveryReferences(u *repox.Unit, m *hooksv1.Delivery, paths []string) {
}

// queueDeliveryDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueDeliveryDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "hooks.v1/Delivery", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

